"""Run-local evidence generator; never alters prior benchmark versions."""
import hashlib,json
from pathlib import Path
ROOT=Path(__file__).parent
def save(p,obj):
    p.write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
def bank(version, entries):
    p=ROOT/version;p.mkdir(exist_ok=False)
    questions={'game':'John Company: Second Edition','scope':'Complete multiplayer core and all standard scenarios, including deregulation and firms. Crown/solo/two-player and optional setup draft excluded.','benchmark_version':version,'questions':[{'id':f'Q{i:03}','question':q} for i,(q,a,ref,novelty) in enumerate(entries,1)]}
    key={'benchmark_version':version,'grading_standard':'Correct: every requested material fact resolved correctly, without contradictory caveat and supported by summary. Partial: material omission or abstention, no material contradiction. Incorrect: material contradiction. Judge each answer separately; do not import facts from other answers. Flag unsupported correct guesses separately. Equivalent wording accepted.','answers':[{'id':f'Q{i:03}','expected_answer':a,'source_references':ref,'novelty':novelty} for i,(q,a,ref,novelty) in enumerate(entries,1)]}
    save(p/'questions.json',questions);save(p/'answer-key.json',key)
    (p/'question-bank.md').write_text('# '+version+' question and answer bank\n\n'+'\n\n'.join(f'## Q{i:03}\n\n{q}\n\n**Expected:** {a}\n\n**Source:** {ref}\n\n**Coverage:** {n}' for i,(q,a,ref,n) in enumerate(entries,1))+'\n')
    save(p/'input-manifest.json',{'selection':'Source-first; seed fixed before summary creation and reader dispatch.','hashes':{x:hashlib.sha256((p/x).read_bytes()).hexdigest() for x in ['questions.json','answer-key.json']},'entry_count':len(entries)})
seed=[
('During attrition, how does an office roll resolve, what extra modifier does the Chairman have, and where do a retiring member, card and fatigue go?', 'Roll separately per office card, +1 per fatigue and an additional +1 for Chairman. 1–2 nothing, 3–4 add fatigue, 5+ retire: member to Pensioners, card flipped into Vacant Offices, fatigue returned to supply.', 'Rules p11; extraction lines 898–916','Attrition thresholds and destinations.'),
('Who may select London Season cards, in what order and with which tiebreakers? What happens to the display and unused pensioners afterward?', 'Each player retiring at least one pensioner must take or discard one display card, descending actual total retirement spending; ties most total windows then PM clockwise order. May peek at display blackmails. Stop when display empty. Discard remaining display and refill three, blackmail down/prestige up even if none taken. Return unretired pensioners to supply.', 'Rules pp11–12; lines 917–928,1002–1014','Retirement rewards, turn order and refresh.'),
('How do the opportunity marker and extra-action laws affect family actions? If four offices are vacant and the marker already sits on Enlist Writer, how many writers can be placed?', 'Normal selected action once, or twice if marker already there at phase start; move marker to main action. Only latest passed extra-action law usable, extra action gets no marker doubling and does not move marker. Four or more vacancies allow one extra writer once per turn, so repeated Enlist Writer can place three total.', 'Rules p13; lines 1076–1104','Family repetition and extra writer stacking.'),
('After Seek Share actions, how are new Company shares created and remaining applicants moved? Where was the initial purchase money paid?', 'Seek Share pays printed empty Stock Exchange space price to bank. At end Family, while Debt and applicants remain, move rightmost applicant into Court and reduce Debt one per share. With no Debt, shift remaining applicants as far right as possible preserving order. Money does not enter Company treasury.', 'Rules p14; lines 1128–1145','Share issue order and money destination.'),
('When hiring, how are vacancies ordered, what consent does hiring your own family require, what happens to promoted fatigue, and what if no candidate or hirer exists?', 'Ascending back-of-card office numbers, insert promotion vacancy in ascending order; own-family hiring needs verbal consent of every other player represented in candidate pool, except Chairman election. Promoted fatigue travels to new card. No candidate or vacant hiring office means skip office; remains vacant and takes no actions including hiring.', 'Rules p14; lines 1146–1169','General hiring exceptions.'),
('How is a Chairman elected, how does a deadlocked election resolve, and does the elected Chairman piece remain a tradable Company share?', 'Candidate must own share, needs consent of players controlling pure majority (>half) current shares; first to achieve support elected. Deadlock former Chairman picks any shareholder including self without Nepotism. Winner moves one share into Chairman slot; still share but cannot trade it or use it for firm investment.', 'Rules p15; lines 1175–1190','Election and Chairman share restrictions.'),
('Explain success-check results, payment, retries, catastrophic destinations and the restriction against dead actions.', 'Commit office treasury money/resources, gather dice then subtract penalty; lowest die 1–2 success, 3–4 failure retry if sufficient resources, 5–6 catastrophe: no more office actions, officeholder to supply, card flipped to Vacant Offices, fatigue to supply (specific office exceptions apply). No action without effect or chance of success.', 'Rules p17; lines 1330–1365','Shared check procedure.'),
('What are the Chairman’s voluntary borrowing and allocation duties, including consent and track limits?', 'May advance Debt three times freely, +£5 Balance each. Each further advancement needs majority-shareholder consent including Chairman share; cannot pass Debt track end. Must allocate all Company Balance to other office treasuries, reducing Balance accordingly; borrowing may interleave allocation while respecting limit.', 'Rules p18; lines 1403–1416','Borrowing and budget allocation.'),
('What must Shipping do with its budget? State ship costs, destinations, consent requirements and the prerequisite for buying Company ships.', 'Spend until at most £2 remains. Lease extra £2, fit shipyard ship £3 without owner consent, buy Company £5 only with no ships remaining on shipyards. Place acquired ships in any sea zone (China eligible once created). Extras return at Refresh.', 'Rules pp19,25; lines 1457–1471,1808–1815','Mandatory Shipping spending and options.'),
('For a President’s Trade action, explain declared regions, dice penalty, routes and capacity, insufficient writers, protected home regions, bonuses and successful-trade limit.', 'Declare home plus only actually reachable regions with sufficient ships and open route; £1 per die minus one per nonhome declared region. Success fill as many orders as possible in declared regions, one per ship, first home port then adjacent own placed writers. Use filled tokens if writers exhausted. Cannot fill another Presidency home region even vacant. Company receives printed order values, President £1 per filled order, writer owner £1 per writer placed; at most one successful trade per President per turn.', 'Rules pp20–21; lines 1540–1582','Core trade whole procedure.'),
('What can a Commander target with Deploy, what produces dice and penalties, and when and how are officer losses checked?', 'Target home, associated region or bordering associated region; exclude another home or another Presidency Company region. Own Company target requires closed order/unrest. Exhaust active officers/regiments for one die each, alliances for printed strength, subtract target and full empire strength; Company-controlled defending strength zero. After every attempt roll per exhausted officer, each 6 removes an officer to its owner supply, never regiment.', 'Rules p22; lines 1617–1650','Deploy legality and loss timing.'),
('On successful Deploy how are loot and trophies calculated and control imposed? What changes if Deploy catastrophically fails?', 'Loot £4 per tower plus faceup loot modifier, at least surviving used officers+1. Pay Commander £1 plus £1 per own used surviving officer, clockwise other officers, then £1 bank per regiment/alliance piece; repeat until empty. Commander trophy per tower; remove tower/dome, capital matching flags, clear unrest/open all orders. Newly conquer: loot token region-side above President, Governor overlay/card to vacant stack, Company control; inward redirect Elephant if formerly poised outward there. Catastrophe loses half trophies rounded up and Commander to supply; still check exhausted officer losses.', 'Rules pp22–23; lines 1648–1650,1674–1710','Deploy outcomes and ownership.'),
('How does Governor Administer work across repeated attempts, including bonuses, tax unrest and stopping?', 'Start printed dice pool; roll pool, no penalty, lose one die after any attempt. Success £1 bonus, extra £1 if preceding roll failed, choose build Company ship in two successful stages, regiment in associated army, or unsplit £2 Balance/President treasury. Tax after first in turn adds unrest. Any unsuccessful check adds unrest. May repeat until stop, pool exhausted or catastrophe (general vacancy rule).', 'Rules p24; lines 1742–1771','Governor diminishing pool and effects.'),
('If Company revenue cannot cover expenses, how do emergency loans work at and below max Debt, how does Standing change, and when are expectations and dividends checked?', 'Expenses £1 per current Debt, officer/regiment excluding Commander, ship in sea zones including China. Emergency loans +£5 each, advance Debt if possible even at maximum continue borrowing; added Debt costs no current-turn interest, then Balance zero. 1–2 emergency loans Standing -1; 3+ -2. Then compare Balance with expectations at current Standing, if below Standing -1. Then optional dividends £1 per share incl Chairman; total dividend payout strictly greater than expectations advances Standing once. Immediate failure when Standing reaches failure.', 'Rules pp25,27; lines 1813–1815,1897–1934','Revenue order and boundary outcomes.'),
('When Company regions face a Crisis, which regions are attacked, in what order and at what strength? How is defense mounted and what happens on successful defense?', 'Resolve primary first then all other Company regions with unrest, Bombay/Madras/Bengal Army order; each Commander orders own regions. Primary normal invasion/rebellion strength + local unrest, secondary unrest only. Exhaust newly active Army strength equal attack or as much as possible; insufficient means Region Loss. Successful defense clears unrest and Commander gains trophy. Vacant Commander replaced by Military Affairs then Chairman, acting substitute gains/loses no trophies.', 'Rules p33; lines 2262–2296','Crisis propagation and compulsory defense.'),
('What happens when a law fails versus passes, including support-zero, policy movement, Prime Minister and effect order?', 'Support -1 or lower fails; discard and resolve dilemma If Failed, Opposition Leader returns marker and becomes PM, moves selected policy one adjacent space either way and resolves it. Zero or higher passes: law with passed laws, PM gains token, selected policy consequence then immediate law effects. Restore vote cards. If legislation fails Company, finish vote then final scoring.', 'Rules p36; lines 2570–2587','Vote outcome branches.'),
('When can or must a Deregulation session be called in the relevant scenarios, and what are its success/failure effects and exceptions from ordinary voting?', '1758/Long1710 start-turn before London: PM may if Standing and/or Debt lined, must if either starred. Pass reduce Debt one per two Debt, Standing to S, PM law token, activate deregulation. Failure raise share VP value up to ±3, law kept, PM stays. No policy and PM may vote against.', 'Rules p36; lines 2588–2601','Deregulation trigger and exceptions.'),
('How can a firm be formed or invested in, where does money come from, and what restrictions apply to Company shares, invested workshops and the ten-share limit?', 'Nonmanager forms by returning eligible Company share or flipping workshop invested; flip own board, create family firm share, value leftmost, £5 bank to London. Later investment manager consent, same share/workshop payment gives £5 London and new share. Weak Company share when Standing/Debt lined prohibited; same-turn share prohibited even traded; Chairman piece unavailable. Invested workshop no bonus/failure VP. Ten-share cap but investments continue without new shares.', 'Rules pp15,38; lines 1184–1187,2679–2724','Firm capital and restrictions.'),
('Explain firm trading strategy, when checks and order filling occur, initiative, capacity, repeat-filled revenue and firm value growth.', 'After investments managers secretly choose home/sea zone and London cash bid; need ship, may choose even closed home. Reveal cash but not strategy. At associated Presidency start reveal/check once with bid dice, pay bank. Success initiative ships minus number of 1/2 dice; President successful Trade gets same calculation. Fill lowest initiative first, President breaks ties; absent/nontrading President wait for Commander/Governors and Chairman breaks ties. Firm fills max ships+1 open connected orders from chosen home once each; prior-fill by others allowed for half listed value rounded down. Revenue India, advance value one space per £6 revenue this turn.', 'Rules p40; lines 2773–2822','Firm competition and trade timing.'),
('How are firm expenses and dividends funded and calculated, and what happens to a failing firm, its shares and workshops?', 'Start Revenue firms act initiative order then others, ties manager windows then PM clockwise. Expenses £1 per ship plus max(shares, firm value); either treasury. If cannot pay dissolution (or emergency rescue): shares Debtors Prison -1 VP each, ships shipyards, charter family, invested workshops stay invested. Dividends only India, £1 per share plus £1 manager each; shareholder may forgo with manager consent. Record total paid retirement marker then sweep remainder India to London.', 'Rules pp41–42; lines 2827–2855,2888–2918','Firm cash flow and failure.'),
]
if __name__=='__main__': bank('seed-v1',seed)
